WITH src AS (SELECT * FROM store_sales WHERE product_id IN (2, 4) AND sale_date BETWEEN '2024-10-01' AND '2024-12-27'), agg AS (SELECT DATE_FORMAT(sale_date, 'yyyy-MM') AS sale_month, MAX(sale_date) AS last_sale_date, COUNT(*) AS row_count FROM src GROUP BY DATE_FORMAT(sale_date, 'yyyy-MM')) SELECT sale_month, last_sale_date, row_count FROM agg ORDER BY last_sale_date, sale_month LIMIT 50;
